+
+/** One live device param, formatted for slot readout. */
+export interface ParamRow {
+  name: string;
+  kind: string;
+  text: string;
+}
+
+export interface AppTrack {
+  key: string;
+  layoutId: number;
+  startChannel: number; // physical fader index 0–15
+  width: number;
