+
+function noteLabel(tag: string): string {
+  const map: Record<string, string> = {
+    C: "C",
+    CSharp: "C♯",
+    D: "D",
+    DSharp: "D♯",
+    E: "E",
+    F: "F",
+    FSharp: "F♯",
+    G: "G",
+    GSharp: "G♯",
+    A: "A",
+    ASharp: "A♯",
+    B: "B",
