+  let nextCh = 1;
+  const alloc = (): number | null => {
+    while (nextCh <= 16 && used.has(nextCh)) nextCh++;
+    if (nextCh > 16) return null;
+    const ch = nextCh;
+    used.add(ch);
+    nextCh++;
+    return ch;
+  };
